        private void UpdateBadge()
        {
            RockMigrationHelper.AddBadgeAttributeValue( "44FE66BE-C43F-43C7-AA8E-5209926C9945", "01C9BA59-D8D4-4137-90A6-B3C06C70BBC3", @"
                {% assign backgroundCheckDate = Person | Attribute:'BackgroundCheckDate' %}
                {% assign backgroundCheckResult = Person | Attribute:'BackgroundCheckResult' %}
                {% assign ministrySafeStatus = Person | Attribute:'MinistrySafeStatus' %}
                {% assign requestInitiatedDate = Person | Attribute:'MinistrySafe_RequestInitiatedDate' %}
                {% assign requestApprovedDate = Person | Attribute:'MinistrySafe_RequestApprovedDate' %}
                {% assign requestExpirationDate = requestApprovedDate | DateAdd:1, 'w' %}

                {% assign currentDate = 'Now' | Date %}
                {% assign daysSinceBackgroundCheck = backgroundCheckDate | DateDiff:currentDate,'d' %}
                {% assign daysSinceExpirationDate = requestExpirationDate | DateDiff:currentDate,'d' %}

                {% assign isDisabled = false %}
                {% assign badgeColor = '' %}

                {% assign tooltipText = '' %}
                {% if backgroundCheckResult == '' and ministrySafeStatus == 'Pending Security Approval' %}
                    {% capture tooltipText %}Pending Approval, Initiated {{requestInitiatedDate | Date:'MM/dd/yyyy'}}{% endcapture %}
                    {% capture badgeColor %}blue{% endcapture %}
                {% elseif backgroundCheckResult == '' and ministrySafeStatus == 'Awaiting Applicant' and daysSinceExpirationDate >= 0 %}
                    {% capture tooltipText %}Request Expired. The Applicant did not complete the request in the allotted time frame. Please resubmit the background check request.{% endcapture %}
                    {% capture badgeColor %}orange{% endcapture %}
                {% elseif backgroundCheckResult == '' and ministrySafeStatus == 'Awaiting Applicant' %}
                    {% capture tooltipText %}Request Approved {{requestApprovedDate | Date:'MM/dd/yyyy'}}, Awaiting Applicant Completion by {{requestExpirationDate | Date:'MM/dd/yyyy'}}{% endcapture %}
                    {% capture badgeColor %}blue{% endcapture %}
                {% elseif backgroundCheckResult == '' and ministrySafeStatus == 'Awaiting MinistrySafe Review' %}
                    {% capture tooltipText %}Awaiting Ministry Safe Review{% endcapture %}
                    {% capture badgeColor %}blue{% endcapture %}
                {% elseif backgroundCheckResult == '' and ministrySafeStatus == 'Awaiting Security Review' %}
                    {% capture tooltipText %}Awaiting Security Review{% endcapture %}
                    {% capture badgeColor %}blue{% endcapture %}
                {% elseif backgroundCheckResult contains 'Failed Pending Review' or ministrySafeStatus contains 'Failed Pending Review' %}
                    {% capture tooltipText %}Failed Pending Review{% endcapture %}
                    {% capture badgeColor %}red{% endcapture %}
                {% elseif backgroundCheckResult contains 'Fail' or ministrySafeStatus contains 'Fail' %}
                    {% capture tooltipText %}Background Check Failed. Please see Background Check notes for more details.{% endcapture %}
                    {% capture badgeColor %}red{% endcapture %}
                {% elseif daysSinceBackgroundCheck > 730 %}
                    {% capture tooltipText %}{{ Person.NickName }} has an expired MinistrySafe Background Check.{% endcapture %}
                    {% capture badgeColor %}yellow{% endcapture %}
                {% elseif backgroundCheckResult == 'Pass' %}
                    {% capture tooltipText %}Passed Background Check. Expiration Date: {{ backgroundCheckDate | DateAdd:2,'y' | Date:'MM/dd/yyyy' }}{% endcapture %}
                    {% capture badgeColor %}green{% endcapture %}
                {% else %}
                    {% capture tooltipText %}{{ Person.NickName }} has not completed a MinistrySafe Background Check.{% endcapture %}
                    {% capture badgeColor %}#939393{% endcapture %}
                {% endif %}

                <div class='rockbadge rockbadge-icon' data-toggle='tooltip' data-original-title='{{ tooltipText }}'>
                    <i class='badge-icon fa fa-shield' style='color: {{badgeColor}};'></i>
                </div>
                " );
            
        }

